cat > s3.mjs <<'EOF'
import { chromium } from 'playwright';
const b = await chromium.launch({headless:true});
const p = await b.newPage();
await p.goto('http://127.0.0.1:60694');
await p.fill('#email','ops@lab.test');
await p.fill('#password','lab-ops-pass');
await p.click('button[type=submit]');
await p.waitForTimeout(1000);
await p.goto('http://127.0.0.1:60694/customers');
const row = p.locator('tr[data-id="c4"]');
console.log('row:', await row.innerText());
await row.locator('button.arch').click();
await p.fill('#mconf','Nordlys AB');
await p.click('#mok');
await p.waitForTimeout(4000);
console.log('toast:', await p.locator('#tmsg').innerText(), await p.locator('#toast').isVisible());
await b.close();
EOF
